{"status":"proposed","agent":"implementer","role":"author","executor":"claude-code","summary":"Phase 2 (tasks 11-20): adds the notes repository and routes, folders, tags, search, trash purge and routes, checklists, attachments and versions. Every query is scoped by user_id, and ids go through requireUuid. Nothing has been typechecked, linted or run. The routers are not mounted in index.ts yet. Notes, folders, tags, search and trash export routers meant for their own prefix. Checklists, attachments and versions export routers meant to be mounted at /api with full sub-paths, because they serve several prefixes.","proposedPatches":[{"baseCommit":"cc839ba8c3b95ef2c0866b23fab4421f8b87b414","files":[{"path":"backend/src/features/notes/repository.ts","action":"add","content":"import type { PoolClient } from 'pg';
import { query, withTransaction } from '../../lib/db.js';
import { notFound } from '../../lib/errors.js';
import { recordActivity } from '../activity/repository.js';
import type { ActivityEvent } from '../activity/repository.js';
import { extractChecklistItems, htmlToPlainText } from '../export/markdown.js';

export interface TagRef {
  id: string;
  name: string;
  color: string;
}

export interface NoteSummary {
  id: string;
  title: string;
  preview: string;
  folderId: string | null;
  folderName: string | null;
  tags: TagRef[];
  pinned: boolean;
  archived: boolean;
  createdAt: string;
  updatedAt: string;
  checklistTotal: number;
  checklistDone: number;
  hasAttachments: boolean;
}

export interface Note extends NoteSummary {
  body: string;
}

export interface SummaryRow {
  id: string;
  title: string;
  preview: string;
  folder_id: string | null;
  folder_name: string | null;
  tags: TagRef[];
  pinned: boolean;
  is_archived: boolean;
  created_at: Date;
  updated_at: Date;
  checklist_total: number;
  checklist_done: number;
  has_attachments: boolean;
}

export type NoteSort = 'updated' | 'created' | 'title' | 'pinned';

export interface NoteFilters {
  folderId?: string;
  tagId?: string;
  pinned?: boolean;
  state?: 'active' | 'archived';
  tasks?: 'open' | 'complete';
  dateField?: 'updated' | 'created';
  from?: string;
  to?: string;
  hasAttachments?: boolean;
}

export interface ListOptions extends NoteFilters {
  sort?: NoteSort;
  limit?: number;
}

// Columns and joins shared by every query that returns note summaries (alias n for notes).
export const SUMMARY_COLUMNS = `
  n.id,
  n.title,
  left(btrim(regexp_replace(n.body_text, '[[:space:]]+', ' ', 'g')), 160) AS preview,
  n.folder_id,
  f.name AS folder_name,
  COALESCE((
    SELECT json_agg(json_build_object('id', t.id, 'name', t.name, 'color', t.color) ORDER BY lower(t.name))
      FROM note_tags nt
      JOIN tags t ON t.id = nt.tag_id AND t.user_id = nt.user_id
     WHERE nt.note_id = n.id AND nt.user_id = n.user_id
  ), '[]'::json) AS tags,
  n.pinned,
  n.is_archived,
  n.created_at,
  n.updated_at,
  (SELECT count(*)::int FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = n.user_id) AS checklist_total,
  (SELECT count(*)::int FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = n.user_id AND c.checked) AS checklist_done,
  EXISTS (SELECT 1 FROM attachments a WHERE a.note_id = n.id AND a.user_id = n.user_id) AS has_attachments
`;

export const SUMMARY_JOINS = 'LEFT JOIN folders f ON f.id = n.folder_id AND f.user_id = n.user_id';

export function mapSummary(row: SummaryRow): NoteSummary {
  return {
    id: row.id,
    title: row.title,
    preview: row.preview,
    folderId: row.folder_id,
    folderName: row.folder_name,
    tags: row.tags,
    pinned: row.pinned,
    archived: row.is_archived,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    checklistTotal: row.checklist_total,
    checklistDone: row.checklist_done,
    hasAttachments: row.has_attachments,
  };
}

// Builds the WHERE clauses for a note query. $1 is always the user id.
// Trashed notes are always excluded; active views also exclude archived notes.
export function buildNoteWhere(
  userId: string,
  filters: NoteFilters
): { clauses: string[]; params: unknown[] } {
  const params: unknown[] = [userId];
  const add = (value: unknown): string => {
    params.push(value);
    return `$${params.length}`;
  };
  const clauses = ['n.user_id = $1', 'n.trashed_at IS NULL'];

  if (filters.pinned) {
    clauses.push('n.pinned = true', 'n.is_archived = false');
  } else if (filters.state === 'archived') {
    clauses.push('n.is_archived = true');
  } else {
    clauses.push('n.is_archived = false');
  }

  if (filters.folderId) {
    clauses.push(`n.folder_id = ${add(filters.folderId)}`);
  }
  if (filters.tagId) {
    clauses.push(
      `EXISTS (SELECT 1 FROM note_tags nt WHERE nt.note_id = n.id AND nt.user_id = $1 AND nt.tag_id = ${add(filters.tagId)})`
    );
  }
  if (filters.tasks === 'open') {
    clauses.push(
      'EXISTS (SELECT 1 FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = $1 AND c.checked = false)'
    );
  } else if (filters.tasks === 'complete') {
    clauses.push(
      'EXISTS (SELECT 1 FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = $1)',
      'NOT EXISTS (SELECT 1 FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = $1 AND c.checked = false)'
    );
  }
  const dateColumn = filters.dateField === 'created' ? 'n.created_at' : 'n.updated_at';
  if (filters.from) {
    clauses.push(`${dateColumn} >= ${add(filters.from)}::date`);
  }
  if (filters.to) {
    clauses.push(`${dateColumn} < (${add(filters.to)}::date + 1)`);
  }
  if (filters.hasAttachments) {
    clauses.push('EXISTS (SELECT 1 FROM attachments a WHERE a.note_id = n.id AND a.user_id = $1)');
  }
  return { clauses, params };
}

const ORDER_BY: Record<NoteSort, string> = {
  updated: 'n.updated_at DESC, n.id',
  created: 'n.created_at DESC, n.id',
  title:
    "lower(CASE WHEN btrim(n.title) = '' THEN 'Untitled note' ELSE n.title END) ASC, n.updated_at DESC, n.id",
  pinned: 'n.pinned DESC, n.updated_at DESC, n.id',
};

export async function listNotes(
  userId: string,
  options: ListOptions
): Promise<{ notes: NoteSummary[]; activeCount: number }> {
  const { clauses, params } = buildNoteWhere(userId, options);
  let limitSql = '';
  if (options.limit !== undefined) {
    params.push(options.limit);
    limitSql = `LIMIT $${params.length}`;
  }
  const orderBy = ORDER_BY[options.sort ?? 'updated'];

  const [list, count] = await Promise.all([
    query<SummaryRow>(
      `SELECT ${SUMMARY_COLUMNS}
         FROM notes n ${SUMMARY_JOINS}
        WHERE ${clauses.join(' AND ')}
        ORDER BY ${orderBy}
        ${limitSql}`,
      params
    ),
    query<{ count: number }>(
      'SELECT count(*)::int AS count FROM notes WHERE user_id = $1 AND trashed_at IS NULL AND is_archived = false',
      [userId]
    ),
  ]);
  return { notes: list.rows.map(mapSummary), activeCount: count.rows[0]?.count ?? 0 };
}

export async function getNote(userId: string, noteId: string): Promise<Note> {
  const result = await query<SummaryRow & { body: string }>(
    `SELECT ${SUMMARY_COLUMNS}, n.body
       FROM notes n ${SUMMARY_JOINS}
      WHERE n.id = $1 AND n.user_id = $2 AND n.trashed_at IS NULL`,
    [noteId, userId]
  );
  const row = result.rows[0];
  if (!row) {
    throw notFound();
  }
  return { ...mapSummary(row), body: row.body };
}

async function requireOwnedFolder(client: PoolClient, userId: string, folderId: string): Promise<void> {
  const result = await client.query('SELECT 1 FROM folders WHERE id = $1 AND user_id = $2', [folderId, userId]);
  if (!result.rowCount) {
    throw notFound();
  }
}

export async function createNote(userId: string, folderId: string | null): Promise<Note> {
  const id = await withTransaction(async (client) => {
    if (folderId) {
      await requireOwnedFolder(client, userId, folderId);
    }
    const inserted = await client.query<{ id: string }>(
      'INSERT INTO notes (user_id, folder_id) VALUES ($1, $2) RETURNING id',
      [userId, folderId]
    );
    const noteId = inserted.rows[0].id;
    await recordActivity(client, { userId, noteId, event: 'created' });
    return noteId;
  });
  return getNote(userId, id);
}

function positiveNumberFromEnv(name: string, fallback: number): number {
  const value = Number(process.env[name]);
  return Number.isFinite(value) && value > 0 ? value : fallback;
}

// Replaces the note's checklist_items with the task items found in its HTML body.
export async function syncChecklistItems(
  client: PoolClient,
  userId: string,
  noteId: string,
  html: string
): Promise<void> {
  await client.query('DELETE FROM checklist_items WHERE note_id = $1 AND user_id = $2', [noteId, userId]);
  const items = extractChecklistItems(html);
  if (items.length === 0) {
    return;
  }
  await client.query(
    `INSERT INTO checklist_items (note_id, user_id, text, checked, position)
     SELECT $1, $2, t.text, t.checked, t.position
       FROM unnest($3::text[], $4::boolean[], $5::int[]) AS t(text, checked, position)`,
    [noteId, userId, items.map((i) => i.text), items.map((i) => i.checked), items.map((i) => i.position)]
  );
}

export async function updateNote(
  userId: string,
  noteId: string,
  changes: { title?: string; body?: string }
): Promise<Note> {
  await withTransaction(async (client) => {
    const current = await client.query<{ title: string; body: string; body_text: string }>(
      `SELECT title, body, body_text FROM notes
        WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL
        FOR UPDATE`,
      [noteId, userId]
    );
    const prior = current.rows[0];
    if (!prior) {
      throw notFound();
    }

    const title = changes.title ?? prior.title;
    const body = changes.body ?? prior.body;
    const titleChanged = title !== prior.title;
    const bodyChanged = body !== prior.body;
    if (!titleChanged && !bodyChanged) {
      return;
    }

    // OD-004: snapshot the pre-update state when no version exists yet or the newest is old enough.
    const intervalSeconds = positiveNumberFromEnv('VERSION_INTERVAL_MINUTES', 5) * 60;
    const hasContent = prior.title.trim() !== '' || prior.body_text.trim() !== '';
    if (hasContent) {
      const due = await client.query<{ due: boolean }>(
        `SELECT NOT EXISTS (
                  SELECT 1 FROM note_versions
                   WHERE note_id = $1 AND user_id = $2
                     AND created_at > now() - make_interval(secs => $3::double precision)
                ) AS due`,
        [noteId, userId, intervalSeconds]
      );
      if (due.rows[0]?.due) {
        await client.query(
          `INSERT INTO note_versions (note_id, user_id, title, body, body_text, reason)
           VALUES ($1, $2, $3, $4, $5, 'autosave')`,
          [noteId, userId, prior.title, prior.body, prior.body_text]
        );
        // OD-005: keep only the newest versions.
        const keep = Math.max(1, Math.floor(positiveNumberFromEnv('VERSION_RETENTION_COUNT', 100)));
        await client.query(
          `DELETE FROM note_versions
            WHERE note_id = $1 AND user_id = $2
              AND id IN (
                SELECT id FROM note_versions
                 WHERE note_id = $1 AND user_id = $2
                 ORDER BY created_at DESC, id DESC
                OFFSET $3
              )`,
          [noteId, userId, keep]
        );
      }
    }

    const bodyText = bodyChanged ? htmlToPlainText(body) : prior.body_text;
    await client.query(
      `UPDATE notes SET title = $3, body = $4, body_text = $5, updated_at = now()
        WHERE id = $1 AND user_id = $2`,
      [noteId, userId, title, body, bodyText]
    );
    if (bodyChanged) {
      await syncChecklistItems(client, userId, noteId, body);
    }
    await recordActivity(client, { userId, noteId, event: 'updated' });
  });
  return getNote(userId, noteId);
}

export async function setPinned(userId: string, noteId: string, pinned: boolean): Promise<Note> {
  const result = await query(
    'UPDATE notes SET pinned = $3 WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL',
    [noteId, userId, pinned]
  );
  if (!result.rowCount) {
    throw notFound();
  }
  return getNote(userId, noteId);
}

export async function setFolder(userId: string, noteId: string, folderId: string | null): Promise<Note> {
  await withTransaction(async (client) => {
    if (folderId) {
      await requireOwnedFolder(client, userId, folderId);
    }
    const result = await client.query(
      'UPDATE notes SET folder_id = $3 WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL',
      [noteId, userId, folderId]
    );
    if (!result.rowCount) {
      throw notFound();
    }
  });
  return getNote(userId, noteId);
}

async function transition(userId: string, noteId: string, sql: string, event: ActivityEvent): Promise<void> {
  await withTransaction(async (client) => {
    const result = await client.query(sql, [noteId, userId]);
    if (!result.rowCount) {
      // Already in the requested state is fine; missing, unowned or trashed is not.
      const exists = await client.query(
        'SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL',
        [noteId, userId]
      );
      if (!exists.rowCount) {
        throw notFound();
      }
      return;
    }
    await recordActivity(client, { userId, noteId, event });
  });
}

export async function archive(userId: string, noteId: string): Promise<Note> {
  await transition(
    userId,
    noteId,
    `UPDATE notes SET is_archived = true, archived_at = now()
      WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL AND is_archived = false`,
    'archived'
  );
  return getNote(userId, noteId);
}

export async function unarchive(userId: string, noteId: string): Promise<Note> {
  await transition(
    userId,
    noteId,
    `UPDATE notes SET is_archived = false, archived_at = NULL
      WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL AND is_archived = true`,
    'unarchived'
  );
  return getNote(userId, noteId);
}

export async function trash(userId: string, noteId: string): Promise<void> {
  await transition(
    userId,
    noteId,
    `UPDATE notes SET trashed_at = now()
      WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL`,
    'trashed'
  );
}

export async function setNoteTags(userId: string, noteId: string, tagIds: string[]): Promise<Note> {
  const unique = Array.from(new Set(tagIds));
  await withTransaction(async (client) => {
    const note = await client.query(
      'SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL FOR UPDATE',
      [noteId, userId]
    );
    if (!note.rowCount) {
      throw notFound();
    }
    if (unique.length > 0) {
      const owned = await client.query(
        'SELECT id FROM tags WHERE user_id = $1 AND id = ANY($2::uuid[])',
        [userId, unique]
      );
      if (owned.rowCount !== unique.length) {
        throw notFound();
      }
    }
    await client.query('DELETE FROM note_tags WHERE note_id = $1 AND user_id = $2', [noteId, userId]);
    if (unique.length > 0) {
      await client.query(
        `INSERT INTO note_tags (note_id, tag_id, user_id)
         SELECT $1, t, $2 FROM unnest($3::uuid[]) AS t`,
        [noteId, userId, unique]
      );
    }
  });
  return getNote(userId, noteId);
}
"},{"path":"backend/src/features/notes/routes.ts","action":"add","content":"import { Router } from 'express';
import type { Request } from 'express';
import { asyncHandler, badRequest, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import {
  archive,
  createNote,
  getNote,
  listNotes,
  setFolder,
  setNoteTags,
  setPinned,
  trash,
  unarchive,
  updateNote,
} from './repository.js';
import type { NoteFilters, NoteSort } from './repository.js';

// Mounted at /api/notes.
export const notesRouter = Router();

const MAX_TITLE_LENGTH = 500;
const MAX_LIST_LIMIT = 500;
const SORTS = ['updated', 'created', 'title', 'pinned'] as const;

function optionalString(value: unknown): string | undefined {
  if (value === undefined || value === '') {
    return undefined;
  }
  if (typeof value !== 'string') {
    throw badRequest();
  }
  return value;
}

function oneOf<T extends string>(value: unknown, allowed: readonly T[]): T | undefined {
  const text = optionalString(value);
  if (text === undefined) {
    return undefined;
  }
  const match = allowed.find((candidate) => candidate === text);
  if (match === undefined) {
    throw badRequest();
  }
  return match;
}

function optionalDate(value: unknown): string | undefined {
  const text = optionalString(value);
  if (text === undefined) {
    return undefined;
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text) || Number.isNaN(Date.parse(text))) {
    throw badRequest('Dates must be in YYYY-MM-DD format.');
  }
  return text;
}

// Shared by the note list and search routes.
export function parseFilters(source: Record<string, unknown>): NoteFilters {
  const filters: NoteFilters = {};
  const folderId = optionalString(source.folderId);
  if (folderId !== undefined) {
    filters.folderId = requireUuid(folderId);
  }
  const tagId = optionalString(source.tagId);
  if (tagId !== undefined) {
    filters.tagId = requireUuid(tagId);
  }
  if (optionalString(source.pinned) === 'true') {
    filters.pinned = true;
  }
  filters.state = oneOf(source.state, ['active', 'archived'] as const);
  filters.tasks = oneOf(source.tasks, ['open', 'complete'] as const);
  filters.dateField = oneOf(source.dateField, ['updated', 'created'] as const);
  filters.from = optionalDate(source.from);
  filters.to = optionalDate(source.to);
  if (optionalString(source.hasAttachments) === 'true') {
    filters.hasAttachments = true;
  }
  return filters;
}

function parseLimit(value: unknown): number | undefined {
  const text = optionalString(value);
  if (text === undefined) {
    return undefined;
  }
  const limit = Number(text);
  if (!Number.isInteger(limit) || limit < 1) {
    throw badRequest();
  }
  return Math.min(limit, MAX_LIST_LIMIT);
}

function bodyOf(req: Request): Record<string, unknown> {
  const body: unknown = req.body;
  return typeof body === 'object' && body !== null && !Array.isArray(body)
    ? (body as Record<string, unknown>)
    : {};
}

function textField(value: unknown, maxLength: number | null): string {
  if (typeof value !== 'string' || value.includes('\u0000')) {
    throw badRequest();
  }
  if (maxLength !== null && value.length > maxLength) {
    throw badRequest(`Text must be at most ${maxLength} characters.`);
  }
  return value;
}

function nullableUuid(value: unknown): string | null {
  return value === null ? null : requireUuid(value);
}

notesRouter.get(
  '/',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const filters = parseFilters(req.query);
    const sort: NoteSort | undefined = oneOf(req.query.sort, SORTS);
    const limit = parseLimit(req.query.limit);
    res.json(await listNotes(userId, { ...filters, sort, limit }));
  })
);

notesRouter.post(
  '/',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const body = bodyOf(req);
    const folderId = body.folderId === undefined ? null : nullableUuid(body.folderId);
    const note = await createNote(userId, folderId);
    res.status(201).json({ note });
  })
);

notesRouter.get(
  '/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    res.json({ note: await getNote(userId, id) });
  })
);

notesRouter.patch(
  '/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const body = bodyOf(req);

    const hasTitle = body.title !== undefined;
    const hasBody = body.body !== undefined;
    const hasFolder = body.folderId !== undefined;
    const hasPinned = body.pinned !== undefined;
    if (!hasTitle && !hasBody && !hasFolder && !hasPinned) {
      throw badRequest('Nothing to update.');
    }

    const title = hasTitle ? textField(body.title, MAX_TITLE_LENGTH) : undefined;
    const html = hasBody ? textField(body.body, null) : undefined;
    const folderId = hasFolder ? nullableUuid(body.folderId) : undefined;
    if (hasPinned && typeof body.pinned !== 'boolean') {
      throw badRequest();
    }

    if (folderId !== undefined) {
      await setFolder(userId, id, folderId);
    }
    if (typeof body.pinned === 'boolean') {
      await setPinned(userId, id, body.pinned);
    }
    if (title !== undefined || html !== undefined) {
      await updateNote(userId, id, { title, body: html });
    }
    res.json({ note: await getNote(userId, id) });
  })
);

notesRouter.post(
  '/:id/archive',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    res.json({ note: await archive(userId, requireUuid(req.params.id)) });
  })
);

notesRouter.post(
  '/:id/unarchive',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    res.json({ note: await unarchive(userId, requireUuid(req.params.id)) });
  })
);

notesRouter.post(
  '/:id/trash',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    await trash(userId, requireUuid(req.params.id));
    res.status(204).end();
  })
);

notesRouter.put(
  '/:id/tags',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const tagIds = bodyOf(req).tagIds;
    if (!Array.isArray(tagIds) || tagIds.length > 100) {
      throw badRequest('tagIds must be a list of tag ids.');
    }
    const ids = tagIds.map((tagId: unknown) => requireUuid(tagId));
    res.json({ note: await setNoteTags(userId, id, ids) });
  })
);
"},{"path":"backend/src/features/folders/routes.ts","action":"add","content":"import { Router } from 'express';
import type { Request } from 'express';
import type { PoolClient } from 'pg';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, badRequest, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';

// Mounted at /api/folders.
export const foldersRouter = Router();

const MAX_NAME_LENGTH = 200;

interface FolderRow {
  id: string;
  parent_id: string | null;
  name: string;
  position: number;
  note_count: number;
}

interface FolderDto {
  id: string;
  parentId: string | null;
  name: string;
  position: number;
  noteCount: number;
}

const FOLDER_SELECT = `
  SELECT f.id, f.parent_id, f.name, f.position,
         (SELECT count(*)::int FROM notes n
           WHERE n.folder_id = f.id AND n.user_id = f.user_id AND n.trashed_at IS NULL) AS note_count
    FROM folders f`;

function toDto(row: FolderRow): FolderDto {
  return {
    id: row.id,
    parentId: row.parent_id,
    name: row.name,
    position: row.position,
    noteCount: row.note_count,
  };
}

function bodyOf(req: Request): Record<string, unknown> {
  const body: unknown = req.body;
  return typeof body === 'object' && body !== null && !Array.isArray(body)
    ? (body as Record<string, unknown>)
    : {};
}

function parseName(value: unknown): string {
  if (typeof value !== 'string' || value.includes('\u0000')) {
    throw badRequest('Folder name is required.');
  }
  const name = value.trim();
  if (name === '' || name.length > MAX_NAME_LENGTH) {
    throw badRequest(`Folder name must be 1 to ${MAX_NAME_LENGTH} characters.`);
  }
  return name;
}

async function fetchFolder(userId: string, id: string): Promise<FolderDto> {
  const result = await query<FolderRow>(`${FOLDER_SELECT} WHERE f.id = $1 AND f.user_id = $2`, [id, userId]);
  const row = result.rows[0];
  if (!row) {
    throw notFound();
  }
  return toDto(row);
}

// The folder and all of its descendants.
async function subtreeIds(client: PoolClient, userId: string, folderId: string): Promise<string[]> {
  const result = await client.query<{ id: string }>(
    `WITH RECURSIVE sub AS (
       SELECT id FROM folders WHERE id = $1 AND user_id = $2
       UNION ALL
       SELECT f.id FROM folders f JOIN sub s ON f.parent_id = s.id WHERE f.user_id = $2
     )
     SELECT id FROM sub`,
    [folderId, userId]
  );
  return result.rows.map((row) => row.id);
}

async function requireOwnedFolder(client: PoolClient, userId: string, folderId: string): Promise<void> {
  const result = await client.query('SELECT 1 FROM folders WHERE id = $1 AND user_id = $2', [folderId, userId]);
  if (!result.rowCount) {
    throw notFound();
  }
}

async function applyOrder(client: PoolClient, userId: string, ids: string[]): Promise<void> {
  if (ids.length === 0) {
    return;
  }
  await client.query(
    `UPDATE folders f SET position = v.pos
       FROM unnest($1::uuid[], $2::int[]) AS v(id, pos)
      WHERE f.id = v.id AND f.user_id = $3`,
    [ids, ids.map((_id, index) => index), userId]
  );
}

async function siblingIds(
  client: PoolClient,
  userId: string,
  parentId: string | null,
  excludeId: string
): Promise<string[]> {
  const result = await client.query<{ id: string }>(
    `SELECT id FROM folders
      WHERE user_id = $1 AND parent_id IS NOT DISTINCT FROM $2::uuid AND id <> $3
      ORDER BY position, created_at, id`,
    [userId, parentId, excludeId]
  );
  return result.rows.map((row) => row.id);
}

foldersRouter.get(
  '/',
  asyncHandler(async (_req, res) => {
    const userId = userIdOf(res);
    const result = await query<FolderRow>(
      `${FOLDER_SELECT} WHERE f.user_id = $1 ORDER BY f.parent_id NULLS FIRST, f.position, f.created_at, f.id`,
      [userId]
    );
    res.json({ folders: result.rows.map(toDto) });
  })
);

foldersRouter.post(
  '/',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const body = bodyOf(req);
    const name = parseName(body.name);
    const parentId = body.parentId === undefined || body.parentId === null ? null : requireUuid(body.parentId);

    const id = await withTransaction(async (client) => {
      if (parentId) {
        await requireOwnedFolder(client, userId, parentId);
      }
      const next = await client.query<{ position: number }>(
        `SELECT COALESCE(MAX(position) + 1, 0)::int AS position FROM folders
          WHERE user_id = $1 AND parent_id IS NOT DISTINCT FROM $2::uuid`,
        [userId, parentId]
      );
      const inserted = await client.query<{ id: string }>(
        'INSERT INTO folders (user_id, parent_id, name, position) VALUES ($1, $2, $3, $4) RETURNING id',
        [userId, parentId, name, next.rows[0].position]
      );
      return inserted.rows[0].id;
    });
    res.status(201).json({ folder: await fetchFolder(userId, id) });
  })
);

foldersRouter.patch(
  '/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const body = bodyOf(req);

    const name = body.name === undefined ? undefined : parseName(body.name);
    const parentProvided = body.parentId !== undefined;
    const newParent = parentProvided ? (body.parentId === null ? null : requireUuid(body.parentId)) : null;
    let position: number | undefined;
    if (body.position !== undefined) {
      if (typeof body.position !== 'number' || !Number.isInteger(body.position) || body.position < 0) {
        throw badRequest('Position must be a non-negative integer.');
      }
      position = body.position;
    }
    if (name === undefined && !parentProvided && position === undefined) {
      throw badRequest('Nothing to update.');
    }

    await withTransaction(async (client) => {
      const current = await client.query<{ parent_id: string | null }>(
        'SELECT parent_id FROM folders WHERE id = $1 AND user_id = $2 FOR UPDATE',
        [id, userId]
      );
      const row = current.rows[0];
      if (!row) {
        throw notFound();
      }

      let parentId = row.parent_id;
      if (parentProvided) {
        if (newParent !== null) {
          await requireOwnedFolder(client, userId, newParent);
          const subtree = await subtreeIds(client, userId, id);
          if (subtree.includes(newParent)) {
            throw badRequest(
              'A folder cannot be moved into itself or one of its subfolders.',
              'invalid_folder_move'
            );
          }
        }
        parentId = newParent;
      }
      const parentChanged = parentId !== row.parent_id;

      if (name !== undefined) {
        await client.query('UPDATE folders SET name = $3 WHERE id = $1 AND user_id = $2', [id, userId, name]);
      }
      if (parentChanged) {
        await client.query('UPDATE folders SET parent_id = $3 WHERE id = $1 AND user_id = $2', [
          id,
          userId,
          parentId,
        ]);
      }
      if (position !== undefined || parentChanged) {
        const ordered = await siblingIds(client, userId, parentId, id);
        const index = position === undefined ? ordered.length : Math.min(position, ordered.length);
        ordered.splice(index, 0, id);
        await applyOrder(client, userId, ordered);
        if (parentChanged) {
          await applyOrder(client, userId, await siblingIds(client, userId, row.parent_id, id));
        }
      }
    });
    res.json({ folder: await fetchFolder(userId, id) });
  })
);

foldersRouter.delete(
  '/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const mode = req.query.notes;
    if (mode !== undefined && mode !== 'move' && mode !== 'uncategorize') {
      throw badRequest('Notes must be moved or left uncategorized.');
    }
    const targetParam = req.query.targetFolderId;
    if (mode === 'move' && typeof targetParam !== 'string') {
      throw badRequest('Choose a folder to move the notes to.');
    }
    const targetFolderId = mode === 'move' ? requireUuid(targetParam) : null;

    await withTransaction(async (client) => {
      const current = await client.query<{ parent_id: string | null }>(
        'SELECT parent_id FROM folders WHERE id = $1 AND user_id = $2 FOR UPDATE',
        [id, userId]
      );
      const row = current.rows[0];
      if (!row) {
        throw notFound();
      }
      const subtree = await subtreeIds(client, userId, id);

      const counted = await client.query<{ count: number }>(
        `SELECT count(*)::int AS count FROM notes
          WHERE user_id = $1 AND folder_id = ANY($2::uuid[]) AND trashed_at IS NULL`,
        [userId, subtree]
      );
      const affected = counted.rows[0]?.count ?? 0;
      if (affected > 0 && mode === undefined) {
        throw badRequest('Choose what to do with the notes in this folder.');
      }

      if (mode === 'move' && targetFolderId) {
        await requireOwnedFolder(client, userId, targetFolderId);
        if (subtree.includes(targetFolderId)) {
          throw badRequest(
            'Notes cannot be moved into the folder being deleted or its subfolders.',
            'invalid_folder_target'
          );
        }
      }

      if (affected > 0) {
        await client.query(
          `UPDATE notes SET folder_id = $3
            WHERE user_id = $1 AND folder_id = ANY($2::uuid[]) AND trashed_at IS NULL`,
          [userId, subtree, mode === 'move' ? targetFolderId : null]
        );
      }

      // Descendant folders go with it (ON DELETE CASCADE); trashed notes lose their folder (SET NULL).
      await client.query('DELETE FROM folders WHERE id = $1 AND user_id = $2', [id, userId]);
      await applyOrder(client, userId, await siblingIds(client, userId, row.parent_id, id));
    });
    res.status(204).end();
  })
);
"},{"path":"backend/src/features/tags/routes.ts","action":"add","content":"import { Router } from 'express';
import type { Request } from 'express';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, badRequest, conflict, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';

// Mounted at /api/tags.
export const tagsRouter = Router();

export const TAG_COLORS = ['gray', 'red', 'orange', 'yellow', 'green', 'blue', 'purple', 'pink'] as const;
const MAX_NAME_LENGTH = 50;

interface TagRow {
  id: string;
  name: string;
  color: string;
  usage_count: number;
}

const TAG_SELECT = `
  SELECT t.id, t.name, t.color,
         (SELECT count(*)::int FROM note_tags nt
            JOIN notes n ON n.id = nt.note_id AND n.user_id = t.user_id
           WHERE nt.tag_id = t.id AND n.trashed_at IS NULL) AS usage_count
    FROM tags t`;

function toDto(row: TagRow): { id: string; name: string; color: string; usageCount: number } {
  return { id: row.id, name: row.name, color: row.color, usageCount: row.usage_count };
}

function bodyOf(req: Request): Record<string, unknown> {
  const body: unknown = req.body;
  return typeof body === 'object' && body !== null && !Array.isArray(body)
    ? (body as Record<string, unknown>)
    : {};
}

function parseName(value: unknown): string {
  if (typeof value !== 'string' || value.includes('\u0000')) {
    throw badRequest('Tag name is required.');
  }
  const name = value.trim();
  if (name === '' || name.length > MAX_NAME_LENGTH) {
    throw badRequest(`Tag name must be 1 to ${MAX_NAME_LENGTH} characters.`);
  }
  return name;
}

function parseColor(value: unknown): string {
  const color = TAG_COLORS.find((candidate) => candidate === value);
  if (!color) {
    throw badRequest('Choose one of the available tag colors.');
  }
  return color;
}

async function assertNameFree(userId: string, name: string, excludeId: string | null): Promise<void> {
  const result = await query(
    `SELECT 1 FROM tags
      WHERE user_id = $1 AND lower(name) = lower($2)
        AND ($3::uuid IS NULL OR id <> $3::uuid)`,
    [userId, name, excludeId]
  );
  if (result.rowCount) {
    throw conflict(`A tag named ${name} already exists.`, 'tag_exists');
  }
}

async function fetchTag(userId: string, id: string): Promise<ReturnType<typeof toDto>> {
  const result = await query<TagRow>(`${TAG_SELECT} WHERE t.id = $1 AND t.user_id = $2`, [id, userId]);
  const row = result.rows[0];
  if (!row) {
    throw notFound();
  }
  return toDto(row);
}

tagsRouter.get(
  '/',
  asyncHandler(async (_req, res) => {
    const userId = userIdOf(res);
    const result = await query<TagRow>(`${TAG_SELECT} WHERE t.user_id = $1 ORDER BY lower(t.name), t.id`, [
      userId,
    ]);
    res.json({ tags: result.rows.map(toDto) });
  })
);

tagsRouter.post(
  '/',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const body = bodyOf(req);
    const name = parseName(body.name);
    const color = body.color === undefined ? 'gray' : parseColor(body.color);
    await assertNameFree(userId, name, null);
    const inserted = await query<{ id: string }>(
      'INSERT INTO tags (user_id, name, color) VALUES ($1, $2, $3) RETURNING id',
      [userId, name, color]
    );
    res.status(201).json({ tag: await fetchTag(userId, inserted.rows[0].id) });
  })
);

tagsRouter.patch(
  '/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const body = bodyOf(req);
    const name = body.name === undefined ? undefined : parseName(body.name);
    const color = body.color === undefined ? undefined : parseColor(body.color);
    if (name === undefined && color === undefined) {
      throw badRequest('Nothing to update.');
    }
    await fetchTag(userId, id);
    if (name !== undefined) {
      await assertNameFree(userId, name, id);
    }
    await query(
      `UPDATE tags SET name = COALESCE($3, name), color = COALESCE($4, color)
        WHERE id = $1 AND user_id = $2`,
      [id, userId, name ?? null, color ?? null]
    );
    res.json({ tag: await fetchTag(userId, id) });
  })
);

tagsRouter.delete(
  '/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    await withTransaction(async (client) => {
      const found = await client.query('SELECT 1 FROM tags WHERE id = $1 AND user_id = $2 FOR UPDATE', [
        id,
        userId,
      ]);
      if (!found.rowCount) {
        throw notFound();
      }
      await client.query('DELETE FROM note_tags WHERE tag_id = $1 AND user_id = $2', [id, userId]);
      await client.query('DELETE FROM tags WHERE id = $1 AND user_id = $2', [id, userId]);
    });
    res.status(204).end();
  })
);
"},{"path":"backend/src/features/search/routes.ts","action":"add","content":"import { Router } from 'express';
import { query } from '../../lib/db.js';
import { asyncHandler, badRequest } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { parseFilters } from '../notes/routes.js';
import { SUMMARY_COLUMNS, SUMMARY_JOINS, buildNoteWhere, mapSummary } from '../notes/repository.js';
import type { SummaryRow } from '../notes/repository.js';

// Mounted at /api/search.
export const searchRouter = Router();

const RESULT_LIMIT = 50;
const MAX_QUERY_LENGTH = 200;

searchRouter.get(
  '/',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const rawQuery = req.query.q;
    if (rawQuery !== undefined && typeof rawQuery !== 'string') {
      throw badRequest();
    }
    const text = (rawQuery ?? '').trim().slice(0, MAX_QUERY_LENGTH);
    const archived = req.query.archived;
    if (archived !== undefined && archived !== '' && archived !== 'only') {
      throw badRequest();
    }
    const parsed = parseFilters(req.query);
    if (text === '' || text.includes('\u0000')) {
      res.json({ results: [] });
      return;
    }

    const { clauses, params } = buildNoteWhere(userId, {
      folderId: parsed.folderId,
      tagId: parsed.tagId,
      dateField: parsed.dateField,
      from: parsed.from,
      to: parsed.to,
      hasAttachments: parsed.hasAttachments,
      state: archived === 'only' ? 'archived' : 'active',
    });
    params.push(text);
    const q = `$${params.length}::text`;

    // OD-007: ts_rank descending, then most recently updated first.
    const result = await query<SummaryRow & { snippet: string | null }>(
      `WITH q AS (
         SELECT websearch_to_tsquery('english', ${q}) || websearch_to_tsquery('simple', ${q}) AS tsq
       )
       SELECT ${SUMMARY_COLUMNS},
              ts_rank(n.search_vector, q.tsq) AS search_rank,
              CASE
                WHEN (to_tsvector('english', n.body_text) || to_tsvector('simple', n.body_text)) @@ q.tsq
                THEN ts_headline(
                  'english', n.body_text, q.tsq,
                  'StartSel=' || chr(2) || ',StopSel=' || chr(3) ||
                  ',MaxFragments=2,MaxWords=25,MinWords=8,FragmentDelimiter=" ... "'
                )
                ELSE NULL
              END AS snippet
         FROM notes n
        CROSS JOIN q
         ${SUMMARY_JOINS}
        WHERE ${clauses.join(' AND ')}
          AND numnode(q.tsq) > 0
          AND n.search_vector @@ q.tsq
        ORDER BY search_rank DESC, n.updated_at DESC, n.id
        LIMIT ${RESULT_LIMIT}`,
      params
    );
    res.json({
      results: result.rows.map((row) => ({ ...mapSummary(row), snippet: row.snippet })),
    });
  })
);
"},{"path":"backend/src/features/trash/purge.ts","action":"add","content":"import { query } from '../../lib/db.js';
import { deleteFile } from '../../lib/storage.js';

const SECONDS_PER_DAY = 24 * 60 * 60;

// OD-003: retention is set per deployment; decimals are allowed so short periods can be tested.
export function trashRetentionSeconds(): number {
  const days = Number(process.env.TRASH_RETENTION_DAYS);
  return (Number.isFinite(days) && days > 0 ? days : 30) * SECONDS_PER_DAY;
}

// SQL fragment that is true while a trashed note is still within retention.
// `paramIndex` is the position of the retention-seconds parameter.
export function withinRetentionSql(column: string, paramIndex: number): string {
  return `${column} > now() - make_interval(secs => $${paramIndex}::double precision)`;
}

// Deletes expired trashed notes (and their attachment files). Returns the number of notes removed.
export async function purgeExpiredTrash(): Promise<number> {
  const expired = await query<{ id: string }>(
    `SELECT id FROM notes
      WHERE trashed_at IS NOT NULL AND NOT (${withinRetentionSql('trashed_at', 1)})`,
    [trashRetentionSeconds()]
  );
  if (expired.rows.length === 0) {
    return 0;
  }
  const ids = expired.rows.map((row) => row.id);

  const files = await query<{ storage_key: string }>(
    'SELECT storage_key FROM attachments WHERE note_id = ANY($1::uuid[])',
    [ids]
  );
  for (const file of files.rows) {
    await deleteFile(file.storage_key);
  }

  const deleted = await query('DELETE FROM notes WHERE id = ANY($1::uuid[]) AND trashed_at IS NOT NULL', [ids]);
  return deleted.rowCount ?? 0;
}

async function runPurge(): Promise<void> {
  try {
    const removed = await purgeExpiredTrash();
    if (removed > 0) {
      console.log(`Trash purge removed ${removed} expired note(s).`);
    }
  } catch (err) {
    console.error('Trash purge failed:', err);
  }
}

export function startTrashPurge(): NodeJS.Timeout {
  const minutes = Number(process.env.TRASH_PURGE_INTERVAL_MINUTES);
  const intervalMs = (Number.isFinite(minutes) && minutes > 0 ? minutes : 60) * 60 * 1000;
  void runPurge();
  const timer = setInterval(() => {
    void runPurge();
  }, intervalMs);
  timer.unref();
  return timer;
}
"},{"path":"backend/src/features/trash/routes.ts","action":"add","content":"import { Router } from 'express';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { deleteFile } from '../../lib/storage.js';
import { recordActivity } from '../activity/repository.js';
import { SUMMARY_COLUMNS, SUMMARY_JOINS, getNote, mapSummary } from '../notes/repository.js';
import type { SummaryRow } from '../notes/repository.js';
import { trashRetentionSeconds, withinRetentionSql } from './purge.js';

// Mounted at /api/trash.
export const trashRouter = Router();

const GONE_MESSAGE = 'This note is no longer in the trash.';

trashRouter.get(
  '/',
  asyncHandler(async (_req, res) => {
    const userId = userIdOf(res);
    const retention = trashRetentionSeconds();
    const result = await query<SummaryRow & { trashed_at: Date }>(
      `SELECT ${SUMMARY_COLUMNS}, n.trashed_at
         FROM notes n ${SUMMARY_JOINS}
        WHERE n.user_id = $1 AND n.trashed_at IS NOT NULL AND ${withinRetentionSql('n.trashed_at', 2)}
        ORDER BY n.trashed_at DESC, n.id`,
      [userId, retention]
    );
    res.json({
      notes: result.rows.map((row) => ({
        ...mapSummary(row),
        trashedAt: row.trashed_at.toISOString(),
        expiresAt: new Date(row.trashed_at.getTime() + retention * 1000).toISOString(),
      })),
    });
  })
);

trashRouter.post(
  '/:id/restore',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);

    const restored = await withTransaction(async (client) => {
      const found = await client.query<{ folder_id: string | null; folder_name: string | null }>(
        `SELECT n.folder_id, f.name AS folder_name
           FROM notes n
           LEFT JOIN folders f ON f.id = n.folder_id AND f.user_id = n.user_id
          WHERE n.id = $1 AND n.user_id = $2 AND n.trashed_at IS NOT NULL
            AND ${withinRetentionSql('n.trashed_at', 3)}
          FOR UPDATE OF n`,
        [id, userId, trashRetentionSeconds()]
      );
      const row = found.rows[0];
      if (!row) {
        throw notFound(GONE_MESSAGE);
      }
      const folderId = row.folder_name === null ? null : row.folder_id;
      await client.query(
        `UPDATE notes SET trashed_at = NULL, restored_at = now(), folder_id = $3
          WHERE id = $1 AND user_id = $2`,
        [id, userId, folderId]
      );
      await recordActivity(client, { userId, noteId: id, event: 'restored' });
      return { folderId, folderName: folderId === null ? null : row.folder_name };
    });

    res.json({
      note: await getNote(userId, id),
      restoredTo: restored.folderId === null ? 'uncategorized' : 'folder',
      folderName: restored.folderName,
    });
  })
);

trashRouter.delete(
  '/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const found = await query(
      'SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NOT NULL',
      [id, userId]
    );
    if (!found.rowCount) {
      throw notFound();
    }

    const files = await query<{ storage_key: string }>(
      'SELECT storage_key FROM attachments WHERE note_id = $1 AND user_id = $2',
      [id, userId]
    );
    for (const file of files.rows) {
      await deleteFile(file.storage_key);
    }
    // Cascades remove checklist items, versions, attachments, activity and tag links.
    await query('DELETE FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NOT NULL', [id, userId]);
    res.status(204).end();
  })
);
"},{"path":"backend/src/features/checklists/routes.ts","action":"add","content":"import { Router } from 'express';
import type { Request } from 'express';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, badRequest, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { recordActivity } from '../activity/repository.js';
import { setChecklistItemChecked } from '../export/markdown.js';

// Mounted at /api; paths below include their /notes or /checklist-items prefix.
export const checklistsRouter = Router();

interface ItemRow {
  id: string;
  note_id: string;
  text: string;
  checked: boolean;
  position: number;
}

function toDto(row: ItemRow): { id: string; noteId: string; text: string; checked: boolean; position: number } {
  return { id: row.id, noteId: row.note_id, text: row.text, checked: row.checked, position: row.position };
}

function summarize(rows: ItemRow[]): { done: number; total: number } {
  return { done: rows.filter((row) => row.checked).length, total: rows.length };
}

function bodyOf(req: Request): Record<string, unknown> {
  const body: unknown = req.body;
  return typeof body === 'object' && body !== null && !Array.isArray(body)
    ? (body as Record<string, unknown>)
    : {};
}

checklistsRouter.get(
  '/notes/:noteId/checklist-items',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    const note = await query('SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL', [
      noteId,
      userId,
    ]);
    if (!note.rowCount) {
      throw notFound();
    }
    const result = await query<ItemRow>(
      `SELECT id, note_id, text, checked, position FROM checklist_items
        WHERE note_id = $1 AND user_id = $2 ORDER BY position, id`,
      [noteId, userId]
    );
    res.json({ items: result.rows.map(toDto), summary: summarize(result.rows) });
  })
);

checklistsRouter.get(
  '/checklist-items/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const result = await query<ItemRow>(
      'SELECT id, note_id, text, checked, position FROM checklist_items WHERE id = $1 AND user_id = $2',
      [id, userId]
    );
    const row = result.rows[0];
    if (!row) {
      throw notFound();
    }
    res.json({ item: toDto(row) });
  })
);

checklistsRouter.patch(
  '/checklist-items/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const checked = bodyOf(req).checked;
    if (typeof checked !== 'boolean') {
      throw badRequest('checked must be true or false.');
    }

    const item = await withTransaction(async (client) => {
      const found = await client.query<ItemRow & { body: string }>(
        `SELECT c.id, c.note_id, c.text, c.checked, c.position, n.body
           FROM checklist_items c
           JOIN notes n ON n.id = c.note_id AND n.user_id = c.user_id
          WHERE c.id = $1 AND c.user_id = $2 AND n.trashed_at IS NULL
          FOR UPDATE OF c, n`,
        [id, userId]
      );
      const row = found.rows[0];
      if (!row) {
        throw notFound();
      }
      await client.query('UPDATE checklist_items SET checked = $3 WHERE id = $1 AND user_id = $2', [
        id,
        userId,
        checked,
      ]);
      const body = setChecklistItemChecked(row.body, row.position, checked);
      if (body !== row.body) {
        await client.query('UPDATE notes SET body = $3, updated_at = now() WHERE id = $1 AND user_id = $2', [
          row.note_id,
          userId,
          body,
        ]);
        await recordActivity(client, { userId, noteId: row.note_id, event: 'updated' });
      }
      return { ...row, checked };
    });
    res.json({ item: toDto(item) });
  })
);
"},{"path":"backend/src/features/attachments/routes.ts","action":"add","content":"import { Router } from 'express';
import type { NextFunction, Request, Response } from 'express';
import multer from 'multer';
import { query } from '../../lib/db.js';
import {
  asyncHandler,
  badRequest,
  notFound,
  payloadTooLarge,
  requireUuid,
  unsupportedMediaType,
} from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { createReadStream, deleteFile, saveBuffer } from '../../lib/storage.js';

// Mounted at /api; paths below include their /notes or /attachments prefix.
// Files are only ever served through the authenticated content route, never as static files.
export const attachmentsRouter = Router();

const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const XLSX = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const PPTX = 'application/vnd.openxmlformats-officedocument.presentationml.presentation';

// OD-002: accepted extensions and the MIME type served for each.
const TYPE_BY_EXTENSION = new Map<string, string>([
  ['png', 'image/png'],
  ['jpg', 'image/jpeg'],
  ['jpeg', 'image/jpeg'],
  ['gif', 'image/gif'],
  ['webp', 'image/webp'],
  ['pdf', 'application/pdf'],
  ['txt', 'text/plain'],
  ['md', 'text/markdown'],
  ['csv', 'text/csv'],
  ['doc', 'application/msword'],
  ['docx', DOCX],
  ['xls', 'application/vnd.ms-excel'],
  ['xlsx', XLSX],
  ['ppt', 'application/vnd.ms-powerpoint'],
  ['pptx', PPTX],
  ['odt', 'application/vnd.oasis.opendocument.text'],
  ['ods', 'application/vnd.oasis.opendocument.spreadsheet'],
  ['odp', 'application/vnd.oasis.opendocument.presentation'],
  ['rtf', 'application/rtf'],
]);

const UNSUPPORTED_MESSAGE =
  'Unsupported file type. Accepted: images, PDF, text and common document formats.';

class UnsupportedFileTypeError extends Error {}

function extensionOf(fileName: string): string {
  const dot = fileName.lastIndexOf('.');
  return dot < 0 ? '' : fileName.slice(dot + 1).toLowerCase();
}

function mimeForFileName(fileName: string): string {
  return TYPE_BY_EXTENSION.get(extensionOf(fileName)) ?? 'application/octet-stream';
}

function maxBytes(): number {
  const value = Number(process.env.ATTACHMENT_MAX_BYTES);
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : 10485760;
}

function formatLimit(bytes: number): string {
  const mb = bytes / (1024 * 1024);
  if (mb >= 1) {
    return `${Number(mb.toFixed(1))} MB`;
  }
  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

// Multer reads header file names as latin1; recover UTF-8 names when the bytes round-trip.
function decodeFileName(raw: string): string {
  let name = raw;
  if (Array.from(raw).every((ch) => ch.charCodeAt(0) <= 255)) {
    const decoded = Buffer.from(raw, 'latin1').toString('utf8');
    if (!decoded.includes('\uFFFD') && Buffer.from(decoded, 'utf8').toString('latin1') === raw) {
      name = decoded;
    }
  }
  const base = name.slice(Math.max(name.lastIndexOf('/'), name.lastIndexOf('\\')) + 1);
  const cleaned = Array.from(base)
    .filter((ch) => ch.charCodeAt(0) >= 32 && ch.charCodeAt(0) !== 127)
    .join('')
    .trim();
  return cleaned.slice(0, 255) || 'file';
}

let uploader: multer.Multer | null = null;

function getUploader(): multer.Multer {
  if (!uploader) {
    uploader = multer({
      storage: multer.memoryStorage(),
      limits: { fileSize: maxBytes(), files: 1 },
      fileFilter: (_req, file, cb) => {
        const name = decodeFileName(file.originalname);
        const expected = TYPE_BY_EXTENSION.get(extensionOf(name));
        const reported = file.mimetype.toLowerCase();
        const typeOk = reported === '' || reported === 'application/octet-stream' || reported === expected;
        if (!expected || !typeOk) {
          cb(new UnsupportedFileTypeError());
          return;
        }
        cb(null, true);
      },
    });
  }
  return uploader;
}

function receiveFile(req: Request, res: Response, next: NextFunction): void {
  getUploader().single('file')(req, res, (err: unknown) => {
    if (err instanceof UnsupportedFileTypeError) {
      next(unsupportedMediaType(UNSUPPORTED_MESSAGE, 'unsupported_file_type'));
      return;
    }
    if (err instanceof multer.MulterError && err.code === 'LIMIT_FILE_SIZE') {
      next(
        payloadTooLarge(`File is too large. The maximum size is ${formatLimit(maxBytes())}.`, 'file_too_large')
      );
      return;
    }
    if (err) {
      next(err);
      return;
    }
    next();
  });
}

interface AttachmentRow {
  id: string;
  note_id: string;
  file_name: string;
  mime_type: string;
  size_bytes: string;
  created_at: Date;
}

function toDto(row: AttachmentRow): {
  id: string;
  noteId: string;
  fileName: string;
  size: number;
  mimeType: string;
  createdAt: string;
} {
  return {
    id: row.id,
    noteId: row.note_id,
    fileName: row.file_name,
    size: Number(row.size_bytes),
    mimeType: row.mime_type,
    createdAt: row.created_at.toISOString(),
  };
}

async function requireOwnedNote(userId: string, noteId: string): Promise<void> {
  const note = await query('SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL', [
    noteId,
    userId,
  ]);
  if (!note.rowCount) {
    throw notFound();
  }
}

function inlineDisposition(fileName: string): string {
  const fallback = Array.from(fileName)
    .map((ch) => (ch.charCodeAt(0) < 32 || ch.charCodeAt(0) > 126 || ch === '"' || ch === '\' ? '_' : ch))
    .join('');
  return `inline; filename="${fallback}"; filename*=UTF-8''${encodeURIComponent(fileName)}`;
}

function isInlineType(mime: string): boolean {
  return mime.startsWith('image/') || mime === 'application/pdf';
}

attachmentsRouter.post(
  '/notes/:noteId/attachments',
  receiveFile,
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    const file = req.file;
    if (!file) {
      throw badRequest('Choose a file to attach.', 'no_file');
    }
    await requireOwnedNote(userId, noteId);

    const fileName = decodeFileName(file.originalname);
    const mimeType = mimeForFileName(fileName);
    const storageKey = await saveBuffer(file.buffer, 'attachments');
    try {
      const inserted = await query<AttachmentRow>(
        `INSERT INTO attachments (note_id, user_id, file_name, mime_type, size_bytes, storage_key)
         VALUES ($1, $2, $3, $4, $5, $6)
         RETURNING id, note_id, file_name, mime_type, size_bytes, created_at`,
        [noteId, userId, fileName, mimeType, file.size, storageKey]
      );
      res.status(201).json({ attachment: toDto(inserted.rows[0]) });
    } catch (err) {
      await deleteFile(storageKey);
      throw err;
    }
  })
);

attachmentsRouter.get(
  '/notes/:noteId/attachments',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    await requireOwnedNote(userId, noteId);
    const result = await query<AttachmentRow>(
      `SELECT id, note_id, file_name, mime_type, size_bytes, created_at FROM attachments
        WHERE note_id = $1 AND user_id = $2 ORDER BY created_at, id`,
      [noteId, userId]
    );
    res.json({ attachments: result.rows.map(toDto) });
  })
);

attachmentsRouter.get(
  '/attachments/:id/content',
  asyncHandler(async (req, res, next) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const result = await query<{ file_name: string; storage_key: string; size_bytes: string }>(
      'SELECT file_name, storage_key, size_bytes FROM attachments WHERE id = $1 AND user_id = $2',
      [id, userId]
    );
    const row = result.rows[0];
    if (!row) {
      throw notFound();
    }

    const mime = mimeForFileName(row.file_name);
    if (isInlineType(mime)) {
      res.setHeader('Content-Disposition', inlineDisposition(row.file_name));
    } else {
      res.attachment(row.file_name);
    }
    res.setHeader('Content-Type', mime);
    res.setHeader('Content-Length', row.size_bytes);
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'private, no-store');

    const stream = createReadStream(row.storage_key);
    stream.on('error', (err: NodeJS.ErrnoException) => {
      if (res.headersSent) {
        res.destroy();
        return;
      }
      res.removeHeader('Content-Disposition');
      res.removeHeader('Content-Length');
      next(err.code === 'ENOENT' ? notFound() : err);
    });
    stream.pipe(res);
  })
);

attachmentsRouter.delete(
  '/attachments/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const result = await query<{ storage_key: string }>(
      'SELECT storage_key FROM attachments WHERE id = $1 AND user_id = $2',
      [id, userId]
    );
    const row = result.rows[0];
    if (!row) {
      throw notFound();
    }
    await deleteFile(row.storage_key);
    await query('DELETE FROM attachments WHERE id = $1 AND user_id = $2', [id, userId]);
    res.status(204).end();
  })
);
