import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { recordActivity } from '../activity/repository.js';
import { displayTitle } from '../export/markdown.js';
import { getNote, syncChecklistItems } from '../notes/repository.js';

// Mounted at /api; paths below include their /notes or /versions prefix.
export const versionsRouter = Router();

const PREVIEW_LENGTH = 140;

function firstCharacters(text: string): string {
  return Array.from(text.replace(/\s+/g, ' ').trim()).slice(0, PREVIEW_LENGTH).join('');
}

// OD-020: an excerpt of the body text, falling back to the title, then to "Untitled note".
function previewOf(bodyText: string, title: string): string {
  return firstCharacters(bodyText) || firstCharacters(displayTitle(title));
}

versionsRouter.get(
  '/notes/:noteId/versions',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    const note = await query('SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL', [
      noteId,
      userId,
    ]);
    if (!note.rowCount) {
      throw notFound();
    }
    const result = await query<{ id: string; created_at: Date; reason: string; title: string; excerpt: string }>(
      `SELECT id, created_at, reason, title, left(body_text, 600) AS excerpt
         FROM note_versions
        WHERE note_id = $1 AND user_id = $2
        ORDER BY created_at DESC, id DESC`,
      [noteId, userId]
    );
    res.json({
      versions: result.rows.map((row) => ({
        id: row.id,
        createdAt: row.created_at.toISOString(),
        reason: row.reason,
        preview: previewOf(row.excerpt, row.title),
      })),
    });
  })
);

versionsRouter.get(
  '/versions/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);
    const result = await query<{
      id: string;
      note_id: string;
      title: string;
      body: string;
      body_text: string;
      reason: string;
      created_at: Date;
    }>(
      `SELECT id, note_id, title, body, body_text, reason, created_at
         FROM note_versions WHERE id = $1 AND user_id = $2`,
      [id, userId]
    );
    const row = result.rows[0];
    if (!row) {
      throw notFound();
    }
    res.json({
      version: {
        id: row.id,
        noteId: row.note_id,
        title: row.title,
        body: row.body,
        bodyText: row.body_text,
        reason: row.reason,
        createdAt: row.created_at.toISOString(),
        preview: previewOf(row.body_text, row.title),
      },
    });
  })
);

versionsRouter.post(
  '/versions/:id/restore',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const id = requireUuid(req.params.id);

    const noteId = await withTransaction(async (client) => {
      const found = await client.query<{
        note_id: string;
        title: string;
        body: string;
        body_text: string;
        current_title: string;
        current_body: string;
        current_body_text: string;
      }>(
        `SELECT v.note_id, v.title, v.body, v.body_text,
                n.title AS current_title, n.body AS current_body, n.body_text AS current_body_text
           FROM note_versions v
           JOIN notes n ON n.id = v.note_id AND n.user_id = v.user_id
          WHERE v.id = $1 AND v.user_id = $2 AND n.trashed_at IS NULL
          FOR UPDATE OF n`,
        [id, userId]
      );
      const row = found.rows[0];
      if (!row) {
        throw notFound();
      }

      // The note's current state is kept as a new version; nothing is pruned.
      await client.query(
        `INSERT INTO note_versions (note_id, user_id, title, body, body_text, reason)
         VALUES ($1, $2, $3, $4, $5, 'restore')`,
        [row.note_id, userId, row.current_title, row.current_body, row.current_body_text]
      );
      await client.query(
        `UPDATE notes SET title = $3, body = $4, body_text = $5, updated_at = now()
          WHERE id = $1 AND user_id = $2`,
        [row.note_id, userId, row.title, row.body, row.body_text]
      );
      await syncChecklistItems(client, userId, row.note_id, row.body);
      await recordActivity(client, { userId, noteId: row.note_id, event: 'version_restored' });
      return row.note_id;
    });
    res.json({ note: await getNote(userId, noteId) });
  })
);
